<?php if(post_password_required()) return; ?><section id="comments" class="comments-area"><h2><?php echo (int)get_comments_number(); ?> Kommentare</h2><?php if(have_comments()): ?><ol><?php wp_list_comments(['style'=>'ol','short_ping'=>true,'avatar_size'=>0]); ?></ol><?php endif; ?><?php if(comments_open()) comment_form(['title_reply'=>'Kommentar schreiben','comment_notes_before'=>'<p>Ihre E-Mail-Adresse wird nicht veröffentlicht. Kommentare werden moderiert.</p>','fields'=>['author'=>'<p><label>Name<br><input name="author" required></label></p>','email'=>'<p><label>E-Mail<br><input name="email" type="email" required></label></p>'],'comment_field'=>'<p><label>Kommentar<br><textarea name="comment" rows="6" required></textarea></label></p>','label_submit'=>'Absenden']); ?></section>
